using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEngine.Rendering;using UnityEditor;using UnityEditor.SceneManagement;using LighthouseKeepers.Presentation.Environment;using LighthouseKeepers.Editor.Environment;
public static class VisualLightingAuthoring {
 public static void Bake(){
  EditorSceneManager.OpenScene("Assets/Scenes/Lab/LK_Lab_Environment.unity");var settings=new LightingSettings{name="Quest practical baked lighting",bakedGI=true,realtimeGI=false,lightmapper=LightingSettings.Lightmapper.ProgressiveCPU,lightmapResolution=10,lightmapMaxSize=1024,directSampleCount=64,indirectSampleCount=128,environmentSampleCount=64};
  const string path="Assets/Settings/Lighting/VisualPass.lighting";var prior=AssetDatabase.LoadAssetAtPath<LightingSettings>(path);if(prior){EditorUtility.CopySerialized(settings,prior);UnityEngine.Object.DestroyImmediate(settings);settings=prior;}else AssetDatabase.CreateAsset(settings,path);Lightmapping.lightingSettings=settings;
  foreach(var l in UnityEngine.Object.FindObjectsByType<Light>(FindObjectsInactive.Include,FindObjectsSortMode.None)) {l.shadows=LightShadows.Soft;if(l.name=="Powered lantern light"){l.lightmapBakeType=LightmapBakeType.Realtime;l.shadows=LightShadows.None;continue;}l.lightmapBakeType=LightmapBakeType.Baked;if(l.type==LightType.Directional||l.name.Contains("rotating beacon"))l.enabled=false;else {l.enabled=true;l.color=new Color(1,.72f,.43f);}}
  var root=GameObject.Find("Visual lighting probes");if(!root)root=new GameObject("Visual lighting probes");foreach(Transform t in root.transform.Cast<Transform>().ToArray())UnityEngine.Object.DestroyImmediate(t.gameObject);
  foreach(var window in new[]{(0f,60f),(3.3f,60f),(6.6f,45f),(6.6f,315f)}){float angle=window.Item2*Mathf.Deg2Rad;var inward=new Vector3(-Mathf.Sin(angle),0,-Mathf.Cos(angle));var go=new GameObject("Baked cold window spill");go.transform.SetParent(root.transform,false);go.transform.position=-inward*3.55f+Vector3.up*(window.Item1+1.65f);go.transform.rotation=Quaternion.LookRotation(inward);var light=go.AddComponent<Light>();light.type=LightType.Rectangle;light.areaSize=new Vector2(.7f,.95f);light.range=4;light.intensity=.65f;light.color=new Color(.36f,.52f,.80f);light.lightmapBakeType=LightmapBakeType.Baked;light.shadows=LightShadows.Soft;}
  var probes=root.GetComponent<LightProbeGroup>();if(!probes)probes=root.AddComponent<LightProbeGroup>();var points=new List<Vector3>();foreach(float y in new[]{.3f,1.6f,3.6f,4.9f,6.9f,8.2f,10.2f,11.5f})foreach(float x in new[]{-2.5f,0,2.5f})foreach(float z in new[]{-2.5f,0,2.5f})points.Add(new Vector3(x,y,z));foreach(float y in new[]{.3f,1.6f,2.7f})foreach(float x in new[]{-2.5f,0,2.5f})foreach(float z in new[]{-10f,-8,-6})points.Add(new Vector3(x,y,z));probes.probePositions=points.ToArray();
