  EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());Debug.Log("VISUAL_BAKE_START");if(!Lightmapping.Bake())throw new Exception("Practical lighting bake failed");
  var renderers=UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsInactive.Include,FindObjectsSortMode.None).Where(r=>r.gameObject.isStatic).OrderBy(r=>EnvironmentLightingBake.PathOf(r.transform),StringComparer.Ordinal).ToArray();
  var capture=typeof(EnvironmentLightingBake).GetMethod("Capture",BindingFlags.NonPublic|BindingFlags.Static);var powered=(EnvironmentLightingPreset)capture.Invoke(null,new object[]{"Powered",renderers});var group=UnityEngine.Object.FindAnyObjectByType<BeaconAndMainsLightingGroup>();var so=new SerializedObject(group);so.FindProperty("poweredPreset").objectReferenceValue=powered;var array=so.FindProperty("bakedRenderers");array.arraySize=renderers.Length;for(int i=0;i<renderers.Length;i++)array.GetArrayElementAtIndex(i).objectReferenceValue=renderers[i];so.ApplyModifiedPropertiesWithoutUndo();
  Directory.CreateDirectory("Assets/Settings/Lighting/Reflections");foreach(var centre in new[]{new Vector3(0,1.6f,-8),new Vector3(0,1.6f,0),new Vector3(0,4.9f,0),new Vector3(0,8.2f,0),new Vector3(0,11.5f,0)}){var go=new GameObject("Baked room reflection "+centre.y+" "+centre.z);go.transform.SetParent(root.transform,false);go.transform.position=centre;var p=go.AddComponent<ReflectionProbe>();p.mode=ReflectionProbeMode.Baked;p.resolution=128;p.hdr=false;p.size=new Vector3(8,3.3f,8);p.boxProjection=true;p.blendDistance=.8f;p.intensity=.65f;p.cullingMask=~0;string dest="Assets/Settings/Lighting/Reflections/Room-"+centre.y+"-"+centre.z+".exr";if(!Lightmapping.BakeReflectionProbe(p,dest))throw new Exception("Probe bake failed "+dest);AssetDatabase.ImportAsset(dest,ImportAssetOptions.ForceSynchronousImport);p.mode=ReflectionProbeMode.Custom;p.customBakedTexture=AssetDatabase.LoadAssetAtPath<Cubemap>(dest);if(!p.customBakedTexture)throw new Exception("Missing baked reflection "+dest);}
  EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());AssetDatabase.SaveAssets();File.WriteAllText("Assets/WatchDemo/Resources/VisualLightingReady.txt","Practical lighting and room probes baked with VisualLightingAuthoring.Bake. Runtime budget: one beacon point light; other sources drive emissive fixtures only.");AssetDatabase.Refresh();File.WriteAllText("artifacts/s4-master/part-c/lighting-bake.txt","PASS maps="+LightmapSettings.lightmaps.Length+" probes="+points.Count+" roomReflections=5; GPU pending");
 }
 [MenuItem("Lighthouse Keepers/Visual Pass/Bind Saved Reflection Probes")]
 public static void BindSavedReflections(){
  EditorSceneManager.OpenScene("Assets/Scenes/Lab/LK_Lab_Environment.unity");
  foreach(var p in UnityEngine.Object.FindObjectsByType<ReflectionProbe>(FindObjectsSortMode.None)){
   if(!p.name.StartsWith("Baked room reflection"))continue;var centre=p.transform.position;string path="Assets/Settings/Lighting/Reflections/Room-"+centre.y+"-"+centre.z+".exr";AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var texture=AssetDatabase.LoadAssetAtPath<Cubemap>(path);if(!texture)throw new Exception("Missing cubemap "+path);p.mode=ReflectionProbeMode.Custom;p.customBakedTexture=texture;EditorUtility.SetDirty(p);
  }EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());AssetDatabase.SaveAssets();EditorSceneManager.OpenScene("Assets/Scenes/Lab/LK_Lab_Environment.unity");int count=UnityEngine.Object.FindObjectsByType<ReflectionProbe>(FindObjectsSortMode.None).Count(p=>p.customBakedTexture||p.bakedTexture);if(count<5)throw new Exception("Probe reference did not survive scene reload");File.WriteAllText("artifacts/s4-master/part-c/probe-reference-fix.txt","PASS "+count+" pre-baked cubemaps assigned and retained after scene reload. Custom mode keeps explicit asset references; no runtime capture.");
 }

